starterHelpers:
def flipRow (r : Nat) : List Move := [.swap (r, 0) (r, 4), .swap (r, 1) (r, 3)]
def mirror : List Move := List.flatten (List.map flipRow (List.range 5))
def half (r c : Nat) : List Move := List.replicate 2 (.rotate (r, c))

